fn source(value: &Value, data_type: &DataType) -> Option<ArrayRef> {
    let target = paimon_type_to_arrow(data_type).unwrap();
    if let ArrowType::Timestamp(unit, _) = &target {
        let ticks = if value.is_null() {
            None
        } else {
            let millis = value.get("millis").unwrap_or(value).as_i64().unwrap();
            let nanos = value.get("nanos").and_then(Value::as_i64).unwrap_or(0);
            let full = i128::from(millis) * 1_000_000 + i128::from(nanos);
            let divisor = match unit {
                TimeUnit::Second => 1_000_000_000,
                TimeUnit::Millisecond => 1_000_000,
                TimeUnit::Microsecond => 1000,
                TimeUnit::Nanosecond => 1,
            };
            if full % divisor != 0 {
                return None;
            }
            Some(i64::try_from(full / divisor).ok()?)
        };
        return Some(
            arrow_cast::cast(
                &(Arc::new(Int64Array::from(vec![ticks])) as ArrayRef),
                &target,
            )
            .unwrap(),
        );
    }
    if matches!(target, ArrowType::Binary) {
        let bytes = value.as_array().map(|v| {
            v.iter()
                .map(|b| b.as_u64().unwrap() as u8)
                .collect::<Vec<_>>()
        });
        return Some(Arc::new(BinaryArray::from(vec![bytes.as_deref()])));
    }
    if let Some(text) = value
        .as_str()
        .filter(|_| matches!(target, ArrowType::Float32 | ArrowType::Float64))
    {
        let number =
            crate::common::number::parse_java_float(text, matches!(target, ArrowType::Float32))
                .unwrap();
        let source: ArrayRef = Arc::new(arrow_array::Float64Array::from(vec![number]));
        return Some(arrow_cast::cast(&source, &target).unwrap());
    }
    Some(super::cast_test_utils::source(value, data_type))
}

fn external(array: &ArrayRef) -> Value {
    if array.is_null(0) {
        return Value::Null;
    }
    match array.data_type() {
        ArrowType::Timestamp(unit, _) => {
            let raw = arrow_cast::cast(array, &ArrowType::Int64).unwrap();
            let value = raw.as_primitive::<Int64Type>().value(0);
            let (millis, nanos) = super::evolution_temporal::timestamp_parts(value, unit);
            json!({"millis":millis,"nanos":nanos})
        }
        ArrowType::Date32 => json!(array.as_primitive::<Date32Type>().value(0)),
        ArrowType::Time32(TimeUnit::Millisecond) => {
            json!(array.as_primitive::<Time32MillisecondType>().value(0))
        }
        ArrowType::Float32 if array.as_primitive::<Float32Type>().value(0).is_infinite() => {
            json!(if array
                .as_primitive::<Float32Type>()
                .value(0)
                .is_sign_negative()
            {
                "-Infinity"
            } else {
                "Infinity"
            })
        }
        ArrowType::Float64 if array.as_primitive::<Float64Type>().value(0).is_infinite() => {
            json!(if array
                .as_primitive::<Float64Type>()
                .value(0)
                .is_sign_negative()
            {
                "-Infinity"
            } else {
                "Infinity"
            })
        }
        _ => super::cast_test_utils::external(array),
    }
}

fn unrepresentable(expected: &Value, target: &ArrowType) -> bool {
    let ArrowType::Timestamp(unit, _) = target else {
        return false;
    };
    let Some(millis) = expected.get("millis").and_then(Value::as_i64) else {
        return false;
    };
    let full = i128::from(millis) * 1_000_000 + i128::from(expected["nanos"].as_i64().unwrap());
    let divisor = match unit {
        TimeUnit::Second => 1_000_000_000,
        TimeUnit::Millisecond => 1_000_000,
        TimeUnit::Microsecond => 1000,
        TimeUnit::Nanosecond => 1,
    };
    full % divisor != 0 || i64::try_from(full / divisor).is_err()
}

#[test]
fn schema_evolution_scalar_casts_match_actual_java() {
    let zone = jiff::tz::TimeZone::system();
    let zone = match zone.iana_name() {
        Some("Asia/Shanghai") => "Asia/Shanghai",
        Some("America/New_York") => "America/New_York",
        Some("UTC" | "Etc/UTC" | "Etc/GMT" | "GMT") => "UTC",
        _ => return,
    };
    let mut tested = 0;
    let mut failures = Vec::new();
    for line in CASES.lines() {
        let case: Value = serde_json::from_str(line).unwrap();
        let from: DataType = serde_json::from_value(case["fields"][0]["type"].clone()).unwrap();
        let original: DataType =
            serde_json::from_value(case["transform"]["fieldRef"]["type"].clone()).unwrap();
        if from != original {
            continue;
        }
        let target: DataType = serde_json::from_value(case["transform"]["type"].clone()).unwrap();
        let target_arrow = paimon_type_to_arrow(&target).unwrap();
        for (row, expected) in case["rows"]
            .as_array()
            .unwrap()
            .iter()
            .zip(case["expected"][zone]["results"].as_array().unwrap())
        {
            let Some(source) = source(&row[0], &from) else {
                continue;
            };
            // These outputs cannot be represented by Arrow, independently of
            // Java's executor. Storage-boundary behavior has dedicated tests.
            if unrepresentable(expected, &paimon_type_to_arrow(&target).unwrap()) {
                continue;
            }
            if matches!(source.data_type(), ArrowType::Binary)
                && row[0].as_array().is_some_and(|bytes| {
                    std::str::from_utf8(
                        &bytes
                            .iter()
                            .map(|v| v.as_u64().unwrap() as u8)
                            .collect::<Vec<_>>(),
                    )
                    .is_err()
                })
            {
                continue;
            }
            let actual = super::nested_evolution::evolve_column(&source, &from, &target);
            tested += 1;
            if expected.get("error").is_some() {
                if actual.is_ok() {
                    failures.push(format!(
                        "{} input {} expected an error, got {:?}",
                        case["name"],
                        row[0],
                        actual.map(|v| external(&v))
                    ));
                }
            } else if !actual.as_ref().is_ok_and(|value| {
                let value = external(value);
                if expected.is_number()
                    && matches!(target_arrow, ArrowType::Float32 | ArrowType::Float64)
                {
                    value.as_f64() == expected.as_f64()
                } else {
                    value == *expected
                }
            }) {
                failures.push(format!(
                    "{} input {} expected {}, got {:?}",
                    case["name"],
                    row[0],
                    expected,
                    actual.map(|v| external(&v))
                ));
            }
        }
    }
    assert!(tested > 500, "too few Java cases: {tested}");
    assert!(
        failures.is_empty(),
        "{} mismatches in {tested} Java cases: {:#?}",
        failures.len(),
        &failures[..failures.len().min(30)]
    );
}

#[test]
fn cast_completion_matches_actual_java_in_three_zones() {
    let mut tested = 0;
    for line in CASES.lines() {
        let case: Value = serde_json::from_str(line).unwrap();
        let actual: DataType = serde_json::from_value(case["fields"][0]["type"].clone()).unwrap();
        let original: DataType =
            serde_json::from_value(case["transform"]["fieldRef"]["type"].clone()).unwrap();
        let target: DataType = serde_json::from_value(case["transform"]["type"].clone()).unwrap();
        let executor = CastExecutor::new(original, actual.clone(), target.clone()).unwrap();
        let target_arrow = paimon_type_to_arrow(&target).unwrap();
        for zone in ["UTC", "Asia/Shanghai", "America/New_York"] {
            let timezone = jiff::tz::TimeZone::get(zone).unwrap();
            for (row, expected) in case["rows"]
                .as_array()
                .unwrap()
                .iter()
                .zip(case["expected"][zone]["results"].as_array().unwrap())
            {
                let Some(source) = source(&row[0], &actual) else {
                    continue;
                };
                let result = executor.cast_in_zone(&source, &timezone);
                let bad_utf8 = matches!(source.data_type(), ArrowType::Binary)
                    && row[0].as_array().is_some_and(|bytes| {
                        let bytes = bytes
                            .iter()
                            .map(|v| v.as_u64().unwrap() as u8)
                            .collect::<Vec<_>>();
                        std::str::from_utf8(&bytes).is_err()
                    });
                if expected.get("error").is_some()
                    || unrepresentable(expected, &target_arrow)
                    || bad_utf8
                {
                    assert!(
                        result.is_err(),
                        "{} {zone} {row}: {expected} -> {result:?}",
                        case["name"]
                    );
                } else {
                    let actual = external(&result.unwrap());
                    if expected.is_number()
                        && matches!(target_arrow, ArrowType::Float32 | ArrowType::Float64)
                    {
                        // Compare IEEE values, not arbitrary-precision JSON spelling.
                        assert_eq!(
                            actual.as_f64(),
                            expected.as_f64(),
                            "{} {zone} {row}",
                            case["name"]
                        );
                    } else {
                        assert_eq!(actual, *expected, "{} {zone} {row}", case["name"]);
                    }
                }
                tested += 1;
            }
        }
    }
    assert!(tested > 4000);
}

#[test]
fn existing_python_java_capability_matrix_is_complete() {
    // 20 by 20 measured pairs, captured before replacing Python pc.cast.
    let types = [
        "BOOLEAN",
        "TINYINT",
        "SMALLINT",
        "INT",
        "BIGINT",
        "FLOAT",
        "DOUBLE",
        "DECIMAL(12,3)",
        "STRING",
        "CHAR(8)",
        "VARCHAR(8)",
        "BINARY(8)",
        "VARBINARY(32)",
        "BYTES",
        "DATE",
        "TIME(3)",
        "TIMESTAMP(3)",
        "TIMESTAMP(6)",
        "TIMESTAMP(3) WITH LOCAL TIME ZONE",
        "TIMESTAMP(6) WITH LOCAL TIME ZONE",
    ];
    let supported = [
        "01111110111000000000",
        "11111111111000000000",
        "11111111111000000000",
        "11111111111000001111",
        "11111111111000001111",
        "01111111111000000000",
        "01111111111000000000",
        "01111111111000000000",
        "11111111111111101111",
        "11111111111111101111",
        "11111111111111101111",
        "00000000111111000000",
        "00000000111111000000",
        "00000000111111000000",
        "00000000111000001111",
        "00000000111000000000",
        "00001000111000111111",
        "00001000111000111111",
        "00001000111000111111",
        "00001000111000111111",
    ];
    for (source, expected) in types.iter().zip(supported) {
        let from: DataType = serde_json::from_value(json!(source)).unwrap();
        for (target, expected) in types.iter().zip(expected.bytes()) {
            let to: DataType = serde_json::from_value(json!(target)).unwrap();
            assert_eq!(
                CastExecutor::supports(&from, &to),
                expected == b'1',
                "{source} -> {target}"
            );
        }
    }
}
